# ==================== 生成逻辑 ====================

count_lock = threading.Lock()
counter = [0]
total = len(TEMPLATES)
start_time = time.time()


def generate_one(filename, category, prompt):
    try:
        resp = client.chat.completions.create(
            model="deepseek-chat",
            messages=[
                {"role": "system", "content": f"你是企业文档撰写专家。生成一份{category}类文档，直接输出正文不要其他解释。"},
                {"role": "user", "content": prompt}
            ],
            temperature=0.7,
            max_tokens=2048,
        )
        text = resp.choices[0].message.content.strip()
        path = os.path.join(OUT_DIR, filename)
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)

        with count_lock:
            counter[0] += 1
            elapsed = time.time() - start_time
            print(f"[{counter[0]:3d}/{total}] {filename} ({elapsed:.0f}s)")

        return filename
    except Exception as e:
        print(f"FAIL {filename}: {e}")
        return None


# ==================== 入口 ====================

if __name__ == "__main__":
    print(f"Generating {total} documents with 10 concurrent workers...\n")

    with ThreadPoolExecutor(max_workers=10) as ex:
        futures = {ex.submit(generate_one, f, c, p): f for f, c, p in TEMPLATES}
        for fut in as_completed(futures):
            fut.result()

    print(f"\nDone! {counter[0]}/{total} documents generated in {time.time()-start_time:.0f}s")
